// Music and sound effects. All audio files live in audio/ and are generated by
// tools/music/make_audio.py (songs are written as note text in tools/music/songs.py).
//
//   #include "bn_music_items.h"
//   #include "bn_sound_items.h"
//   sb::play_music(bn::music_items::sled_song);
//   sb::sfx(bn::sound_items::sfx_jump);
#ifndef SB_AUDIO_H
#define SB_AUDIO_H

#include "bn_music_item.h"
#include "bn_sound_item.h"

namespace sb
{
    // Starts a looping song at the standard music volume (or remembers it while music is off).
    void play_music(const bn::music_item& song);
    void stop_music();

    // Plays a short tune once (jingles), then music stays stopped until play_music is called.
    void play_jingle(const bn::music_item& jingle);

    // Plays a sound effect at the standard volume. Sound effects play even when music is off.
    void sfx(const bn::sound_item& sound);

    // Select button toggles music (sb::update() calls this).
    void toggle_music();
}

#endif
